import java.util.Map;
/**
 * This class is for holding the information that are generated by the class 'HuffmanEncoderDecoder'.
 * We could passed a 3 different separated objects, but these allow it to simply group into a single object called 'HuffmanCodebook'
 */
public class HuffmanCodebook {
    public final Map<Character, Integer> frequencies;
    public final Map<Character, String> codes;
    public final HuffmanTreeNode root;

    /**
     * Constructor
     */
    public HuffmanCodebook(Map<Character, Integer> frequencies, Map<Character, String> codes, HuffmanTreeNode root) {
        this.frequencies = frequencies;
        this.codes = codes;
        this.root = root;
    }
}